import assert from 'node:assert/strict';import {readFile,writeFile} from 'node:fs/promises';import {render,SERVICES} from '../../scripts/deploy/release.mjs';
const revision=process.argv[2];assert.match(revision,/^[a-f0-9]{40}$/);const api='https://ko-card-game.onrender.com',front='https://ko-card-game-vr69.onrender.com';const checks=[];
for(const [role,id]of Object.entries(SERVICES)){const d=(await render(`services/${id}/deploys?limit=5`)).find(x=>x.deploy.status==='live')?.deploy;assert.equal(d?.commit?.id,revision);checks.push({role,revision,deployId:d.id});}
async function json(path,headers={}){const r=await fetch(api+path,{headers,cache:'no-store',signal:AbortSignal.timeout(30000)});assert.equal(r.status,200,path);return r.json();}
assert.equal((await json('/api/healthz')).revision,revision);const cookie=(await readFile('/tmp/ko-latest-balance/admin-cookie.txt','utf8')).trim();
for(const path of ['/api/collection','/api/decks/options']){const data=await json(path,{Cookie:cookie});assert.ok(data.cards.length>0);assert.ok(data.cards.every(c=>c.rarity!=='TOKEN'&&!c.isToken&&!c.isChampionToken));assert.ok(!data.cards.some(c=>c.id==='b6b6247d-4e98-4cfb-8fa6-5479afec48f3'));if(data.craftableCards)assert.ok(data.craftableCards.every(c=>c.rarity!=='TOKEN'&&!c.isToken&&!c.isChampionToken));checks.push({path,visibleCards:data.cards.length,gradeAndFlagTokensExcluded:true});}
const cards=(await json('/api/cards')).cards;const wolf=cards.find(c=>c.id==='b6b6247d-4e98-4cfb-8fa6-5479afec48f3');assert.equal(wolf.isToken,true);assert.equal(wolf.rarity,'TOKEN');checks.push({name:wolf.name,rarity:wolf.rarity,isToken:wolf.isToken,version:wolf.version});
const sovereign=cards.find(c=>c.name==='소버린');assert.equal(sovereign.version,2);checks.push({name:sovereign.name,version:sovereign.version,effectUnchanged:true});
assert.equal((await fetch(front+'/version.json',{cache:'no-store'}).then(r=>r.json())).revision,revision);
for(const path of ['/','/online/match/token-release-'+revision.slice(0,12)]){const html=await fetch(front+path,{cache:'no-store'}).then(r=>r.text());const entry=html.match(/<script[^>]+type="module"[^>]+src="([^"]+)"/)?.[1];assert.ok(entry);const js=await fetch(new URL(entry,front)).then(r=>r.text());assert.ok(js.includes(revision));checks.push({path,entry,revisionMatches:true});}
const receipt={checkedAt:new Date().toISOString(),revision,checks,productionCombatActionsCreated:0,productionWritesByVerification:0,physicalDeviceTesting:false};await writeFile('docs/qa/20261112-token-classification/production-release.json',JSON.stringify(receipt,null,2));console.log(JSON.stringify(receipt));
